const fetchCategorias = async () => {
  if (!hasData) {
    setCategorias([]);
    return;
  }

  // Buscar categorias do setor que são globais (loja_id null) ou específicas da loja atual
  let query = supabase
    .from('categorias')
    .select('*')
    .or(`loja_id.is.null,loja_id.eq.${storeId}`)
    .order('nome');

  if (setorSelecionado !== 'Todos') {
    const setorFilterCats = [normalizeSetorForDb(setorSelecionado)];
    query = query.in('setor', setorFilterCats);
  }

  const { data, error } = await query;

  if (error) {
    toast({ title: 'Erro ao carregar categorias', variant: 'destructive' });
    return;
  }
  setCategorias(data || []);

  // Also fetch ALL categories for the dropdowns (when changing sectors)
  if (hasData) {
    const allQuery = supabase
      .from('categorias')
      .select('*')
      .or(`loja_id.is.null,loja_id.eq.${storeId}`)
      .order('nome');

    const { data: allData } = await allQuery;
    setAllCategorias(allData || []);
  }
};

