const deleteCategory = async (id: number) => {
  if (!hasData) {
    toast({ title: 'Selecione uma loja primeiro', variant: 'destructive' });
    return;
  }

  // Verificar se a categoria tem produtos associados
  let checkQuery = supabase
    .from('produtos_master') // Updated from 'produtos' to 'produtos_master'
    .select('id')
    .eq('categoria_id', id);

  checkQuery = applyStoreFilter(checkQuery);
  const { data: produtosAssociados, error: checkError } = await checkQuery;

  if (checkError) {
    toast({
      title: 'Erro ao verificar produtos da categoria',
      variant: 'destructive',
    });
    return;
  }

  if (produtosAssociados && produtosAssociados.length > 0) {
    toast({
      title: 'Não é possível deletar categoria',
      description: `Esta categoria possui ${produtosAssociados.length} produto(s) associado(s). Remova ou altere a categoria dos produtos primeiro.`,
      variant: 'destructive',
    });
    return;
  }

  let deleteQuery = supabase.from('categorias').delete().eq('id', id);

  deleteQuery = applyStoreFilter(deleteQuery);
  const { error } = await deleteQuery;

  if (error) {
    toast({ title: 'Erro ao deletar categoria', variant: 'destructive' });
    return;
  }

  toast({ title: 'Categoria deletada com sucesso!' });
  fetchCategorias();
  fetchProdutos();
};

