const deleteDeprecatedCategories = async () => {
  try {
    const { data: cats } = await supabase
      .from('categorias')
      .select('id, nome');
    const deprecated =
      cats?.filter((c) => c.nome.toLowerCase().includes('deprecated')) || [];

    if (deprecated.length === 0) {
      toast({ title: 'Nenhuma categoria deprecated encontrada.' });
      return;
    }

    if (
      !confirm(
        `Confirma a exclusão de ${deprecated.length} categorias deprecated?`,
      )
    )
      return;

    const ids = deprecated.map((c) => c.id);
    const { error } = await supabase
      .from('categorias')
      .delete()
      .in('id', ids);

    if (error) throw error;
    toast({ title: 'Categorias limpas com sucesso!' });
    fetchCategorias();
  } catch (e) {
    handleError(e, { domain: 'produtos', operation: 'cleanCategories', showToast: false });
    toast({ title: 'Erro ao limpar categorias', variant: 'destructive' });
  }
};

